CREATE TABLE IF NOT EXISTS "AsistenciaPersonal" ("id" TEXT PRIMARY KEY,"usuarioId" TEXT NOT NULL REFERENCES "Usuario"("id"),"fecha" DATE NOT NULL,"horaEntrada" TIMESTAMP(3),"horaSalida" TIMESTAMP(3),"estado" "EstadoAsistencia" NOT NULL DEFAULT 'PRESENTE',"descuentoAplicadoMonto" DECIMAL(12,2) NOT NULL DEFAULT 0,"anuladoPorAdmin" BOOLEAN NOT NULL DEFAULT FALSE,"motivoAnulacion" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("usuarioId","fecha"));
CREATE TABLE IF NOT EXISTS "PermisoPersonal" ("id" TEXT PRIMARY KEY,"usuarioId" TEXT NOT NULL REFERENCES "Usuario"("id"),"fechaSolicitud" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"fechaPermiso" DATE NOT NULL,"motivo" TEXT NOT NULL,"descripcion" TEXT NOT NULL,"comprobanteUrl" TEXT NOT NULL DEFAULT '',"estado" "EstadoPermiso" NOT NULL DEFAULT 'SOLICITADO',"aprobadoPorId" TEXT REFERENCES "Usuario"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "PuntoAsistencia" ("sucursalId" TEXT PRIMARY KEY REFERENCES "Sucursal"("id"),"latitud" DECIMAL(10,7) NOT NULL CHECK ("latitud" BETWEEN -90 AND 90),"longitud" DECIMAL(10,7) NOT NULL CHECK ("longitud" BETWEEN -180 AND 180),"activo" BOOLEAN NOT NULL DEFAULT TRUE,"modificadoPorNombre" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ReglaNomina" ("id" TEXT PRIMARY KEY,"vigenteDesde" TEXT NOT NULL UNIQUE,"inicioControl" DATE NOT NULL,"divisorDia" INTEGER NOT NULL CHECK ("divisorDia" BETWEEN 1 AND 31),"descuentoFaltaPct" DECIMAL(5,2) NOT NULL CHECK ("descuentoFaltaPct" BETWEEN 0 AND 100),"descuentoTardanzaPct" DECIMAL(5,2) NOT NULL CHECK ("descuentoTardanzaPct" BETWEEN 0 AND 100),"diasNoLaborables" JSONB NOT NULL,"activa" BOOLEAN NOT NULL DEFAULT TRUE,"modificadoPorNombre" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "ConfiguracionLaboral" ("id" TEXT PRIMARY KEY,"usuarioId" TEXT NOT NULL REFERENCES "Usuario"("id"),"vigenteDesde" TEXT NOT NULL,"sueldoMensual" DECIMAL(12,2) NOT NULL CHECK ("sueldoMensual">=0),"fechaIngreso" DATE NOT NULL,"fechaBaja" DATE,"horaEntrada" TEXT NOT NULL,"horaSalida" TEXT NOT NULL,"toleranciaMinutos" INTEGER NOT NULL CHECK ("toleranciaMinutos" BETWEEN 0 AND 120),"diasLaborales" JSONB NOT NULL,"sucursalesAutorizadas" JSONB NOT NULL,"activo" BOOLEAN NOT NULL DEFAULT TRUE,"modificadoPorNombre" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("usuarioId","vigenteDesde"));
CREATE TABLE IF NOT EXISTS "MarcacionPersonal" ("id" TEXT PRIMARY KEY,"asistenciaId" TEXT NOT NULL REFERENCES "AsistenciaPersonal"("id"),"usuarioId" TEXT NOT NULL REFERENCES "Usuario"("id"),"sucursalId" TEXT NOT NULL REFERENCES "Sucursal"("id"),"tipo" TEXT NOT NULL CHECK ("tipo" IN ('ENTRADA','SALIDA')),"origen" TEXT NOT NULL CHECK ("origen" IN ('GPS','REGULARIZACION')),"latitud" DOUBLE PRECISION,"longitud" DOUBLE PRECISION,"precisionMetros" DOUBLE PRECISION,"distanciaMetros" DOUBLE PRECISION,"centroLatitud" DOUBLE PRECISION,"centroLongitud" DOUBLE PRECISION,"muestraAt" TIMESTAMP(3),"registradoAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"minutosTarde" INTEGER NOT NULL DEFAULT 0,"justificacion" TEXT NOT NULL DEFAULT '',"solicitudHash" TEXT NOT NULL,UNIQUE("asistenciaId","tipo"));
CREATE INDEX IF NOT EXISTS "MarcacionPersonal_usuarioId_registradoAt_idx" ON "MarcacionPersonal"("usuarioId","registradoAt");
CREATE TABLE IF NOT EXISTS "GestionPermiso" ("permisoId" TEXT PRIMARY KEY REFERENCES "PermisoPersonal"("id"),"goceHaberes" BOOLEAN NOT NULL DEFAULT TRUE,"motivoDecision" TEXT NOT NULL DEFAULT '',"decididoPorNombre" TEXT,"retirado" BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS "IncidenciaPersonal" ("id" TEXT PRIMARY KEY,"usuarioId" TEXT NOT NULL REFERENCES "Usuario"("id"),"fecha" DATE NOT NULL,"descripcion" TEXT NOT NULL,"estado" TEXT NOT NULL DEFAULT 'PENDIENTE',"justificaDia" BOOLEAN NOT NULL DEFAULT FALSE,"resolucion" TEXT NOT NULL DEFAULT '',"resueltoPorNombre" TEXT,"resueltoAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "IncidenciaPersonal_usuarioId_fecha_idx" ON "IncidenciaPersonal"("usuarioId","fecha");
CREATE TABLE IF NOT EXISTS "LiquidacionPersonal" ("id" TEXT PRIMARY KEY,"usuarioId" TEXT NOT NULL REFERENCES "Usuario"("id"),"periodo" TEXT NOT NULL,"version" INTEGER NOT NULL,"estado" TEXT NOT NULL DEFAULT 'CERRADA',"snapshot" JSONB NOT NULL,"totalBruto" DECIMAL(12,2) NOT NULL,"totalDescuentos" DECIMAL(12,2) NOT NULL,"totalNeto" DECIMAL(12,2) NOT NULL,"creadoPorNombre" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"motivoAnulacion" TEXT NOT NULL DEFAULT '',"anuladaAt" TIMESTAMP(3),UNIQUE("usuarioId","periodo","version"));
CREATE UNIQUE INDEX IF NOT EXISTS "LiquidacionPersonal_activa_key" ON "LiquidacionPersonal"("usuarioId","periodo") WHERE "estado"='CERRADA';

ALTER TABLE "ConfiguracionLaboral" ADD COLUMN IF NOT EXISTS "margenEntradaMinutos" INTEGER NOT NULL DEFAULT 0 CHECK ("margenEntradaMinutos" BETWEEN 0 AND 240);
ALTER TABLE "ConfiguracionLaboral" ADD COLUMN IF NOT EXISTS "margenSalidaMinutos" INTEGER NOT NULL DEFAULT 0 CHECK ("margenSalidaMinutos" BETWEEN 0 AND 240);
